public static class Seq
{
    public static IEnumerable<long> Collatz(long start)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(start, 1);
        return Iterate();

        IEnumerable<long> Iterate()
        {
            long n = start;
            yield return n;
            while (n != 1)
            {
                n = n % 2 == 0 ? n / 2 : 3 * n + 1;
                yield return n;
            }
        }
    }

    public static IEnumerable<T> Interleave<T>(IEnumerable<T> a, IEnumerable<T> b)
    {
        using var ea = a.GetEnumerator();
        using var eb = b.GetEnumerator();
        bool hasA = ea.MoveNext(), hasB = eb.MoveNext();
        while (hasA || hasB)
        {
            if (hasA) { yield return ea.Current; hasA = ea.MoveNext(); }
            if (hasB) { yield return eb.Current; hasB = eb.MoveNext(); }
        }
    }

    public static IEnumerable<(T Value, int Count)> RunLengths<T>(this IEnumerable<T> source)
    {
        var cmp = EqualityComparer<T>.Default;
        using var e = source.GetEnumerator();
        if (!e.MoveNext()) yield break;
        T current = e.Current;
        int count = 1;
        while (e.MoveNext())
        {
            if (cmp.Equals(e.Current, current)) { count++; continue; }
            yield return (current, count);
            current = e.Current;
            count = 1;
        }
        yield return (current, count);
    }

    public static IEnumerable<T[]> Windows<T>(this IEnumerable<T> source, int size)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(size, 1);
        return Iterate();

        IEnumerable<T[]> Iterate()
        {
            var window = new Queue<T>(size);
            foreach (var item in source)
            {
                window.Enqueue(item);
                if (window.Count > size) window.Dequeue();
                if (window.Count == size) yield return window.ToArray();
            }
        }
    }
}

unitTests:
static IEnumerable<int> Naturals() { for (int i = 1; ; i++) yield return i; }

Test("collatz", () =>
{
    CheckEq(Seq.Collatz(6), new long[] { 6, 3, 10, 5, 16, 8, 4, 2, 1 });
    CheckEq(Seq.Collatz(1), new long[] { 1 });
    CheckEq(Seq.Collatz(27).Count(), 112);
    CheckThrows<ArgumentOutOfRangeException>(() => Seq.Collatz(0));
});

Test("interleaving", () =>
{
    CheckEq(Seq.Interleave(new[] { 1, 2, 3 }, new[] { 10, 20 }), new[] { 1, 10, 2, 20, 3 });
    CheckEq(Seq.Interleave(new int[0], new[] { 5, 6 }), new[] { 5, 6 });
    CheckEq(Seq.Interleave(Naturals(), Naturals().Select(n => -n)).Take(5), new[] { 1, -1, 2, -2, 3 });
});

Test("run lengths", () =>
{
    CheckEq("aaabcc".RunLengths().Select(r => $"{r.Value}{r.Count}"), new[] { "a3", "b1", "c2" });
    CheckEq(new int[0].RunLengths().Count(), 0);
    CheckEq(Naturals().Select(n => n / 3).RunLengths().Take(3).Select(r => r.Count), new[] { 2, 3, 3 });
});

Test("sliding windows", () =>
{
    var w = new[] { 1, 2, 3, 4 }.Windows(2).ToList();
    CheckEq(w.Count, 3);
    CheckEq(w[0], new[] { 1, 2 });
    CheckEq(w[2], new[] { 3, 4 });
    CheckEq(new[] { 1 }.Windows(2).Count(), 0);
    CheckEq(Naturals().Windows(3).Skip(10).First(), new[] { 11, 12, 13 });
    CheckThrows<ArgumentOutOfRangeException>(() => new[] { 1 }.Windows(0));
});

